const fs = require("fs");
const path = require("path");

const TEMPLATES_ROOT = path.join(
    __dirname,
    "..",
    "src",
    "templates",
    "metadata",
    "view"
);
const OVERRIDES_ROOT = path.join(TEMPLATES_ROOT, "overrides");
const OUTPUT = path.join(TEMPLATES_ROOT, "registry.generated.ts");

const BANNER = `/**
 * AUTO-GENERATED by \`npm run generate:template-registry\`, which also runs from
 * next.config.js on \`next dev\` and \`next build\`. DO NOT HAND-EDIT.
 *
 * Every overrides/{PARTNER}/{gwdmVersion|default}/index.mdx is registered
 * here, with its optional sibling components.tsx. To add a template, create
 * the folder - nothing else needs editing.
 */`;

const listDirs = dir =>
    fs
        .readdirSync(dir, { withFileTypes: true })
        .filter(entry => entry.isDirectory())
        .map(entry => entry.name);

function discover() {
    if (!fs.existsSync(OVERRIDES_ROOT)) return [];

    return listDirs(OVERRIDES_ROOT)
        .flatMap(partner =>
            listDirs(path.join(OVERRIDES_ROOT, partner))
                .filter(version =>
                    fs.existsSync(
                        path.join(OVERRIDES_ROOT, partner, version, "index.mdx")
                    )
                )
                .map(version => ({
                    partner,
                    version,
                    hasComponents: fs.existsSync(
                        path.join(
                            OVERRIDES_ROOT,
                            partner,
                            version,
                            "components.tsx"
                        )
                    ),
                    source: `overrides/${partner}/${version}/index.mdx`,
                }))
        )
        .sort((a, b) => a.source.localeCompare(b.source));
}

function render(templates) {
    const imports = templates
        .flatMap(({ partner, version, hasComponents }, i) => {
            const base = `./overrides/${partner}/${version}`;
            const lines = [
                `import T${i}, { meta as m${i} } from "${base}/index.mdx";`,
            ];
            if (hasComponents) {
                lines.push(
                    `import { makeComponents as c${i} } from "${base}/components";`
                );
            }
            return lines;
        })
        .join("\n");

    const entries = templates
        .map(
            ({ partner, version, hasComponents, source }, i) => `    {
        partner: ${JSON.stringify(partner)},
        version: ${JSON.stringify(version)},
        source: ${JSON.stringify(source)},
        Template: T${i},
        meta: m${i},
        makeComponents: ${hasComponents ? `c${i}` : "undefined"},
    },`
        )
        .join("\n");

    return `${BANNER}

import { GeneratedTemplate } from "./meta";
${imports}

export const generatedTemplates: GeneratedTemplate[] = [
${entries}
];
`;
}

function generateTemplateRegistry() {
    const templates = discover();
    const next = render(templates);
    const current = fs.existsSync(OUTPUT)
        ? fs.readFileSync(OUTPUT, "utf-8")
        : null;

    // Only write on change, so a dev server restart does not trigger a
    // rebuild of everything that imports the registry.
    if (current !== next) fs.writeFileSync(OUTPUT, next);

    return templates;
}

module.exports = generateTemplateRegistry;

if (require.main === module) {
    const templates = generateTemplateRegistry();
    console.log(
        `Wrote src/templates/metadata/view/registry.generated.ts (${templates.length} templates)`
    );
    templates.forEach(t =>
        console.log(`  ${t.partner} ${t.version} -> ${t.source}`)
    );
}
